SELECT lb.shop_id, lb.shop_name, lb.source_type, lb.source_id, lb.source_code, lb.transport_no, lbd.track_status, lbd.track_no FROM logistics_bill lb LEFT JOIN logistics_bill_detail lbd ON lb.id = lbd.main_id AND lbd.is_deleted = FALSE WHERE lb.is_deleted = FALSE
AND lb.source_id IN
#{sourceId}

SELECT COUNT(id) AS count, track_status AS tabFlag FROM logistics_bill_detail
${permissionSql}
WHERE is_deleted=false GROUP BY track_status

SELECT lbd.id, lb.sales_platform AS salesPlatform, lb.shop_id AS shopId, lb.shop_name AS shopName, lb.source_type AS sourceType, lb.order_type AS orderType, lb.source_id AS sourceId, lb.source_code AS sourceCode, lb.outstock_id AS outstockId, lb.outstock_code AS outstockCode, lb.channel_id AS channelId, lb.order_time AS orderTime, lb.delivery_time AS deliveryTime, lb.transport_no AS transportNo, lb.to_country AS toCountry, lbd.track_status AS trackStatus , lbd.track_no AS trackNo, lbd.track_query_mode AS trackQueryMode, lc.name AS channelName FROM logistics_bill_detail lbd RIGHT JOIN logistics_bill lb ON lbd.main_id=lb.id LEFT JOIN logistics_channel lc ON lc.id=lb.channel_id and lc.is_deleted=false WHERE lb.is_deleted=false and (lbd.is_deleted=false or lbd.is_deleted is null)
AND lbd.track_status in
#{item}
AND lbd.track_no in
#{item}
AND lb.source_code in
#{item}
AND lb.sales_platform in
#{item}
AND lb.order_type in
#{item}
AND lb.shop_id in
#{item}
AND lb.order_time >= #{params.orderTimeList[0]} and (#{params.orderTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > lb.order_time
AND lb.delivery_time >= #{params.deliveryTimeList[0]} and (#{params.deliveryTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > lb.delivery_time
AND lb.channel_id in
#{item}
AND lbd.track_status in
#{item}
${params.permissionSql}
ORDER BY
${item.field} ${item.sort}
lb.create_time DESC

SELECT lbd.id, lb.sales_platform AS salesPlatform, lb.shop_id AS shopId, lb.shop_name AS shopName, lb.source_type AS sourceType, lb.order_type AS orderType, lb.source_id AS sourceId, lb.source_code AS sourceCode, lb.outstock_id AS outstockId, lb.outstock_code AS outstockCode, lb.channel_id AS channelId, lb.order_time AS orderTime, lb.delivery_time AS deliveryTime, lb.transport_no AS transportNo, lb.to_country AS toCountry, lbd.track_status AS trackStatus , lbd.track_no AS trackNo, lbd.track_query_mode AS trackQueryMode, lc.name AS channelName FROM logistics_bill_detail lbd RIGHT JOIN logistics_bill lb ON lbd.main_id=lb.id LEFT JOIN logistics_channel lc ON lc.id=lb.channel_id and (lbd.is_deleted=false or lbd.is_deleted is null) WHERE lb.is_deleted=false and lbd.is_deleted=false
AND lbd.id IN
#{id}
AND lbd.track_status in
#{item}
AND lb.source_code in
#{item}
AND lbd.track_no in
#{item}
AND lb.sales_platform in
#{item}
AND lb.order_type in
#{item}
AND lb.shop_id in
#{item}
AND lb.order_time >= #{params.orderTimeList[0]} and (#{params.orderTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > lb.order_time
AND lb.delivery_time >= #{params.deliveryTimeList[0]} and (#{params.deliveryTimeList[1]}::TIMESTAMP + INTERVAL '1 DAY' ) > lb.delivery_time
AND lb.channel_id in
#{item}
AND lbd.track_status in
#{item}
