${item.field} ${item.sort}
lb.create_time DESC

SELECT DISTINCT lbd.id AS detailId, lb.id, lb.sales_platform AS salesPlatform, lb.shop_id AS shopId, lb.shop_name AS shopName, lb.source_type AS sourceType, lb.order_type AS orderType, lb.source_id AS sourceId, lb.source_code AS sourceCode, lb.outstock_id AS outstockId, lb.outstock_code AS outstockCode, lb.channel_id AS channelId, lb.order_time AS orderTime, lb.delivery_time AS deliveryTime, lb.transport_no AS transportNo, lb.to_country AS toCountry, lbd.track_no AS trackNo FROM logistics_bill_detail lbd LEFT JOIN logistics_bill lb ON lbd.main_id=lb.id ANd lb.is_deleted = false WHERE lbd.is_deleted = false
AND lb.transport_no IN
#{transportNo}
